import os
from rich.console import Console
from io import StringIO

def test_tty_compatible_1():
    with StringIO() as f:
        os.environ["TTY_COMPATIBLE"] = "1"
        console = Console(file=f)
        assert console.is_terminal is True
        del os.environ["TTY_COMPATIBLE"]

def test_tty_compatible_0():
    # We need to make sure it's a terminal by default or use a fake file that is a tty
    class FakeTTY:
        def isatty(self):
            return True
        def write(self, s):
            pass
        def flush(self):
            pass

    f = FakeTTY()
    os.environ["TTY_COMPATIBLE"] = "0"
    console = Console(file=f)
    assert console.is_terminal is False
    del os.environ["TTY_COMPATIBLE"]

def test_tty_compatible_unset():
    class FakeTTY:
        def isatty(self):
            return True
        def write(self, s):
            pass
        def flush(self):
            pass

    f = FakeTTY()
    if "TTY_COMPATIBLE" in os.environ:
        del os.environ["TTY_COMPATIBLE"]
    console = Console(file=f)
    assert console.is_terminal is True

def test_tty_compatible_other():
    class FakeTTY:
        def isatty(self):
            return True
        def write(self, s):
            pass
        def flush(self):
            pass

    f = FakeTTY()
    os.environ["TTY_COMPATIBLE"] = "maybe"
    console = Console(file=f)
    assert console.is_terminal is True
